package queue

import (
	"errors"
	"time"
)

// PriorityQueueWrapper wraps a PriorityQueue to implement the Queue interface.
type PriorityQueueWrapper struct {
	*PriorityQueue
}

// Put adds items to the queue.
func (pw *PriorityQueueWrapper) Put(items ...interface{}) error {
	if len(items) == 0 {
		return nil
	}

	// Convert interface{} items to Item items
	priorityItems := make([]Item, 0, len(items))
	for _, item := range items {
		if priorityItem, ok := item.(Item); ok {
			priorityItems = append(priorityItems, priorityItem)
		} else {
			return errors.New("item does not implement Item interface")
		}
	}

	// Call the underlying PriorityQueue's Put method
	return pw.PriorityQueue.Put(priorityItems...)
}

// Get retrieves items from the queue.
func (pw *PriorityQueueWrapper) Get(number int64) ([]interface{}, error) {
	items, err := pw.PriorityQueue.Get(int(number))
	if err != nil {
		return nil, err
	}

	// Convert []Item to []interface{}
	interfaceItems := make([]interface{}, len(items))
	for i, item := range items {
		interfaceItems[i] = item
	}

	return interfaceItems, nil
}

// Poll retrieves items from the queue with a timeout.
func (pw *PriorityQueueWrapper) Poll(number int64, timeout time.Duration) ([]interface{}, error) {
	// For simplicity, delegate to Get
	// A full implementation would handle the timeout
	return pw.Get(number)
}

// Peek returns the next item in the queue without removing it.
func (pw *PriorityQueueWrapper) Peek() (interface{}, error) {
	item := pw.PriorityQueue.Peek()
	if item == nil {
		return nil, ErrEmptyQueue
	}
	return item, nil
}

// TakeUntil takes a function and returns a list of items that
// match the checker until the checker returns false.
func (pw *PriorityQueueWrapper) TakeUntil(checker func(item interface{}) bool) ([]interface{}, error) {
	// Since PriorityQueue doesn't have TakeUntil, we'll implement it by
	// repeatedly calling Get(1) until the checker returns false or queue is empty
	var result []interface{}

	for !pw.Empty() {
		items, err := pw.Get(1)
		if err != nil {
			return result, err
		}

		if len(items) == 0 {
			break
		}

		item := items[0]
		if !checker(item) {
			// Put the item back since we didn't consume it
			pw.Put(item)
			break
		}

		result = append(result, item)
	}

	return result, nil
}

// Len returns the number of items in the queue.
func (pw *PriorityQueueWrapper) Len() int64 {
	return int64(pw.PriorityQueue.Len())
}

// Dispose prevents further reads/writes and frees resources.
func (pw *PriorityQueueWrapper) Dispose() []interface{} {
	items := pw.PriorityQueue.Dispose()

	// Convert []Item to []interface{}
	interfaceItems := make([]interface{}, len(items))
	for i, item := range items {
		interfaceItems[i] = item
	}

	return interfaceItems
}

// NewPriorityQueueWrapper creates a new PriorityQueueWrapper.
func NewPriorityQueueWrapper(hint int, allowDuplicates bool) *PriorityQueueWrapper {
	return &PriorityQueueWrapper{
		NewPriorityQueue(hint, allowDuplicates),
	}
}
